class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        unordered_map<int, vector<int>> dp;
        vector<int> max_len(k + 1, 0);
        for (int x : nums) {
            if (!dp.count(x)) dp[x] = vector<int>(k + 1, 0);
            auto& cur_x = dp[x];
            for (int j = k; j >= 0; --j) {
                cur_x[j] = cur_x[j] + 1;
                if (j > 0) cur_x[j] = max(cur_x[j], max_len[j - 1] + 1);
                max_len[j] = max(max_len[j], cur_x[j]);
            }
        }
        return max_len[k];
    }
};

class Solution {
    public int maximumLength(int[] nums, int k) {
        Map<Integer, int[]> dp = new HashMap<>();
        int[] maxLen = new int[k + 1];
        for (int x : nums) {
            dp.putIfAbsent(x, new int[k + 1]);
            int[] curX = dp.get(x);
            for (int j = k; j >= 0; --j) {
                curX[j] = curX[j] + 1;
                if (j > 0) curX[j] = Math.max(curX[j], maxLen[j - 1] + 1);
                maxLen[j] = Math.max(maxLen[j], curX[j]);
            }
        }
        return maxLen[k];
    }
}

var maximumLength = function(nums, k) {
    const dp = new Map();
    const maxLen = new Int32Array(k + 1);
    for (const x of nums) {
        if (!dp.has(x)) dp.set(x, new Int32Array(k + 1));
        const curX = dp.get(x);
        for (let j = k; j >= 0; --j) {
            curX[j] = curX[j] + 1;
            if (j > 0) curX[j] = Math.max(curX[j], maxLen[j - 1] + 1);
            maxLen[j] = Math.max(maxLen[j], curX[j]);
        }
    }
    return maxLen[k];
